INSERT INTO `article_single_page` VALUES (1,'about','[[],[{\"view_id\":\"1\",\"text\":[\"<p>我們測試看看</p>\"],\"img\":[\"\"]}],[]]',1),(3,'privacy','[\"\",\"<p>本公司致力於遵守保護個人資料的相關法令及本公司隱私保護政策，妥善管理和保護用戶的隱私權。</p><ol>\\t<li>本公司明確告知下述&quot;2.個人資料使用目的&quot; ，並透過合法公正的方法獲取個人資料。</li>\\t<li>除去相關法例允許的情況，本公司僅在下述&quot;2.個人資料使用目的&quot;的範圍内使用個人資料。</li>\\t<li>為安全管理所獲得之個人資料，本公司會採取必要且適當的措施。</li>\\t<li>除下述&quot;3，個人資料向第三方的提供&quot;規定的用途外，本公司不會將個人資料提供給第三方。</li>\\t<li>本公司在接獲顧客本人向下述&quot;4，諮詢窗口&quot;提出個人資料的確認、修正、停止使用、刪除等相關要求時，將會立即處理。</li></ol><p style=\\\"margin-left:36.0pt;\\\">&nbsp;</p><p><strong>1</strong><strong>．個人資料的定義</strong></p><p>個人資料包括姓名、住址、電話號碼等能夠辨識該個人身分的資料。本公司個人資料的蒐集對象包括顧客、股東、徵才活動的應徵者、本公司董事及各類職員。<br />&nbsp;</p><p><strong>2</strong><strong>．個人資料的使用目的</strong></p><p>本公司蒐集得來的個人資料，將用於以下用途。</p><p><strong>顧客相關個人資料</strong></p><ul>\\t<li>對諮詢、商談、修改、補充的對應、確認及記錄</li>\\t<li>關於宣傳單、電子郵件等進行的商品、服務、活動等訊息的提供</li>\\t<li>商品的寄送</li>\\t<li>商品開發及其他服務的改善</li></ul><p><strong>股東相關個人資料</strong></p><ul>\\t<li>公司法規定的權力之行使、義務的履行</li>\\t<li>向股東提供關於本公司經營狀況的訊息</li>\\t<li>各種法令規定的記錄、資料製作等股東的管理</li></ul><p><strong>應徵者相關個人資料</strong></p><ul>\\t<li>錄用、徵才活動之應徵者的聯絡及有關本公司運營及錄取訊息提供</li>\\t<li>將徵才過程的記錄作為對求職者的資料管理</li>\\t<li>其它必要的使用</li></ul><p><strong>職員相關個人資料</strong></p><ul>\\t<li>員工業務面之聯絡</li>\\t<li>向職員的薪資（工資・獎金・各種津貼等）支付</li>\\t<li>人事・勞務管理相關各種手續的履行（退休金、勞工保險、產假等）</li>\\t<li>福利保障的提供</li>\\t<li>職員的健康管理</li></ul><p><strong>＊ 有關Cookie的使用</strong><br />將訪問網站的訪客訊息在電腦（硬碟驅動器）上進行登記管理的技術被稱作&quot;Cookie&quot;。在本公司的網站中，為了客戶更方便地使用本公司的網站，有使用Cookie技術的頁面。通過瀏覽器改變Cookie的使用設定從而拒絕使用Cookie時，可能導致商品的購買等部分或全部服務無法利用。另外，在不能確定具體個人的情況下，為了調查客戶的網站使用情況，我們使用Cookie技術。<br />&nbsp;</p><p><strong>3</strong><strong>．個人資料向第三方的提供</strong></p><p>除了以下情況外，本公司不會將個人資料提供給第三方。</p><ol>\\t<li>已取得本人同意。</li>\\t<li>本公司集團内部共同使用的情況<br />\\t本公司與網站內所經營之相關品牌（以下簡稱&quot;樂勢整合創意有限公司&quot;）為一體來展開事業。因此，對於本公司從客戶、股東、徵才活動的應徵者及職員處所獲得的所有個人資料，在上述&quot;2.個人資料使用目的&quot;所須的範圍内，可與迅銷集團共同使用。</li>\\t<li>其它法令許可的情況\\t<ul>\\t\\t<li>爲了保護生命、身體或財產而必須提供，但獲得本人同意又很困難的情況</li>\\t\\t<li>在達成使用目的所必須的範圍内，將個人資料的全部或部分委託給第三方的情況</li>\\t\\t<li>因合併或其他理由進行事業繼承時必須提供個人資料的情況等<br />\\t\\t&nbsp;</li>\\t</ul>\\t</li></ol><p><strong>4</strong><strong>．個人資料的確認、修正、停止使用、刪除等諮詢窗口</strong></p><p>本公司在收到提出個人資料的確認、修正、停止使用、刪除等要求時，按照規定手續確認為本人後，將迅速予以對應。個人資料的相關諮詢，請透過本公司網站首頁的諮詢窗口聯絡我們。<br /><br />本公司爲了對應個人資料保護相關工作安排的變更或法令的變更，針對上述的&quot;隱私保護政策&quot;之變更及修改將不另行通知，敬請諒解。</p>\",\"<p>cccc</p>\"]',0),(4,'guide','[\"<p><span style=\\\"color: rgb(0, 0, 0); font-size: 13px; font-weight: normal; line-height: 25px; background-color: rgb(249, 249, 249);\\\">歡迎來到聚粹台灣網站&quot;GAPURE.COM&quot;。我們在下列條款</span></p>\",\"<ol>\\t<li><strong>網站使用條款</strong><br />\\t歡迎來到聚粹台灣網站&quot;GAPURE.COM&quot;。我們在下列條款的範圍内向您提供資訊。如果您訪問本網站，您將接受協議。請仔細閲讀該協議。<br />\\t<br />\\t本協議適用于使用者和台灣聚粹 / 樂勢整合創意有限公司之間。您將在GAPURE的授權下訪問本網站。<br />\\tGAPURE保留隨時對本協議修改的權利。當您進行購買或使用本網站時，您的權利將遵循本協議當前的最新内容。如您不贊同原有或修改後的條款，請不要使用本網站。<br />\\t<br />\\t本協議附屬於本網站的&quot;隱私權保護方針&quot;。為避免爭議，當本協議和&quot;隱私權保護方針&quot;内容發生衝突時將遵循本協議。如您對自己在本協議中的權利存在疑問，請通過以下方式聯絡我們。<br />\\t&nbsp;</li>\\t<li><strong>通行證和網站登錄</strong><br />\\tGAPURE授予您有限權力登錄和利用本網站，在沒有得到GAPURE明確的書面同意的情況下，不得允許下載或修改本網站及其部分内容。本通行證不適用於任何將本網站及其内容轉賣或用於商業用途的行爲；或者任何收集或利用本公司商品目錄、描述及價格的行爲；或者任何轉載本網站及其内容的行爲；或者任何利用本網站的資料收集、robots、相似數據的收集及調取工具的行爲。<br />\\t在沒有得到GAPURE明確的書面同意的情況下，任何對本網站及其部分内容的複製、販賣、轉賣、訪問或商業利用的行爲都是不被允許的。在沒有得到GAPURE明確的書面同意的情況下，框取或利用框取技術對任何對本公司商標、LOGO、所有權資訊（包括圖像、文字、網頁排版、表格）及其關聯公司（包括母公司及其下屬公司、品牌）進行框取的行爲都是不被允許的。任何越權使用都將導致GAPURE終結對您的允許或授權。<br />\\t&nbsp;</li>\\t<li><strong>商標和服務商標</strong><br />\\t除非另有説明，所有包括在本網站内的名稱、圖形、設計、LOGO、網頁標題、按鈕圖標、文字、商業標記、商業外觀和服務名稱均為GAPURE及其授權者、贊助商或供應商的商標，並且受到商標註冊保護法保護。不得以任何可能對GAPURE造成混淆、詆毀或有損GAPURE信譽的方式使用本商標。<br />\\t<br />\\tGAPURE及其LOGO在不受限制的條件下屬於GAPURE及其關聯企業的註冊商標。對GAPURE任何商標的侵權都是不被允許的。<br />\\t&nbsp;</li>\\t<li><strong>版權所有</strong><br />\\t該網站上所有内容，包括產品設計（包括任何及所有相關的附屬材料）均屬於GAPURE及其授權者，並且受到版權法和/或外觀設計專利保護。除了出於個人非營利性目的的使用，您不得通過電子郵件或其他任何方式使用、展示、複製、轉發、修改、散布、傳播、出售、出版、創造衍生產品、廣播、發行、展示或以任何方式利用全部或部分網站内容。在沒有得到GAPURE明確書面協議的情況下不得使用任何產品設計。<br />\\t&nbsp;</li>\\t<li>本公司的產品<br />\\tGAPURE試圖在其產品説明方面盡可能做到準確。然而，GAPURE並不保證產品和價格説明或本網站的其他内容是準確地、完整的、可靠的、最新的或是毫無差錯的。<br />\\t&nbsp;</li>\\t<li><strong>交流及其他内容</strong><br />\\t訪問者可以向我們的客戶服務部門提出建議、想法、意見或其他訊息，只要内容不是非法、淫穢、威脅、誹謗、侵犯隱私、侵犯知識產權或以其他方式損害第三方或引起反感的，並且不包含病毒軟體、政治宣傳、商業招攬、連鎖信、大宗郵件或任何形式的&quot;垃圾郵件&quot;。您不得使用虛假的電子郵件地址、冒充任何人或實體、或以其他方式誤導至任何原版内容。<br />\\t<br />\\t如您提交了材料，您自動授予GAPURE及其關連公司非獨佔的、免版稅的、永久的、不可撤銷的，且完全轉授的權利對該材料進行使用、複製、修復、改編、出版、翻譯、創作衍生作品、發佈及在世界上通過任何媒體進行展示。您授予GAPURE及其關連公司和被授權者可自由選擇使用相關内容中您所提供的名字的權利。您聲名並保證對所提供内容擁有所有權或控制權；您所提供的内容是正確的；任何使用您所提供的内容的行爲不會對任何人或實體造成傷害；您所提供的内容不會侵犯任何第三者的知識產權、公開權、隱私權或其他權利，並且這些内容不帶有誹謗色彩；並對GAPURE及其關連公司收到的任何因您所提供内容造成的索賠給予賠償。GAPURE有權利但並無義務監控、編輯或者刪除任何活動或内容。GAPURE不會對您或任何第三者在網上的共享内容承擔責任。<br />\\t&nbsp;</li>\\t<li><strong>免責聲明及責任限制</strong><br />\\t本網站及所有所含資訊是由GAPURE依&quot;現狀&quot;及&quot;現有&quot;基礎提供。至於本網站的運營和可用性或有關信息、内容、材料或該網站上顯示的商品，GAPURE不作任何形式的明示或暗示的申明或擔保。您明確同意您為使用本網站自行承擔風險。在法律完全許可的範圍內，GAPURE否認所有明示或暗示的保證，包括但不僅限於出於某種特定目的而對適銷性和適用性作出的保證。GAPURE不保證本網站及其服務或發送的電子郵件不存在病毒或其他有害内容或錯誤。GAPURE將不承擔任何因使用本網站產生的損害，包括但不限於直接的、間接的、偶然的、懲罰性的及相應的損害。對任何有關本網站、本條款和條件及私隱條款方面的問題，GAPURE所承擔的責任將不超過NT$500.00。<br />\\t&nbsp;</li>\\t<li><strong>索賠問題</strong><br />\\t您同意對GAPURE及其關連公司就任何因您違反使用條款或任何因您提供的資訊或採取的行爲而蒙受的損失、負債、成本、費用及開支，包括合理的律師訴訟費進行賠償。我們將及時通知您有關此類索賠、訴訟或法律程序。|<br />\\t&nbsp;</li>\\t<li><strong>隱私問題</strong><br />\\t請閲讀我們的隱私權保護方針，它將對您訪問本網站進行管理，並幫助您了解我們的處理方法。<br />\\t&nbsp;</li>\\t<li><strong>安全問題</strong><br />\\t請閲讀我們的隱私權保護方針中有關安全問題的部分。<br />\\t&nbsp;</li>\\t<li><strong>凖據法及專屬管轄權</strong><br />\\t本協議依照中華民國的法律構建，並受其管理。如發生任何爭議，您和GAPURE同意遵從專屬管轄權和中華民國台北法院管轄地的法律。<br />\\t&nbsp;</li>\\t<li><strong>不可抗力</strong><br />\\t對於超出GAPURE控制範圍的原因造成的推遲或無法履行義務，GAPURE將不承擔責任。這些原因包括但不僅限於：天災、戰爭或恐怖主義、自然災害、依照法律法規及政策徵收的費用、貨物和服務上的短缺。在這些原因影響下GAPURE可能推遲發貨且不承擔相應責任，但在這些原因導致未出貨部分被取消的情況下，GAPURE將把相應貨款退還給顧客<br />\\t&nbsp;</li>\\t<li><strong>一般條款</strong><br />\\t繼續使用本網站表示您承認已閲讀並理解該使用條款，表示您同意依照這些條款和條件行動並受其約束。在沒有GAPURE事先書面同意的情況下不得對該使用條款有任何的調整或修改。GAPURE沒有處理您或其他人的違反條款行爲並不意味著GAPURE將放棄對其後果及類似違反行爲的處理權力。<br />\\t<br />\\t如果您作爲一個團體的代理人（包括代表您的雇主），那您和您的團體將共同且分別承擔本協議中規定的義務。<br />\\t<br />\\t如果法院發現本協議中有任何部分無效、違法或者不可執行，那該部分將被扣除，其餘部分將在法律允許的最大範圍内繼續保持其有效性和可強制執行性。</li></ol><p><br />如果您對於本使用條款有任何問題，請寫信至 service@gapure.com</p>\",\"\"]',0);
