INSERT INTO `faq` VALUES (1,'',0,'0000-00-00','購買須知','購買須知','','[[],[{\"view_id\":\"1\",\"input\":[\"多久可以收到商品?\"],\"text\":[\"<p>現貨商品:若您全訂單皆為現貨商品,當天下午3:00前的單,往後推兩個工作天會幫</p><p>您寄出商品!(不含列假日!)</p><p>預購商品:若商品無現貨需等待預購追加,正常預購追加期為14~30天</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"超商取貨可否延長取貨時間?\"],\"text\":[\"<p>很抱歉! 超商取貨時間皆為超商所制定的7日內,無法再延長時間喔!</p><p>提醒您,若超過兩次未領取超商取貨訂單,該帳號將被本商場列為黑名單! 請您愛</p><p>惜自身帳號使用之權利!</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"訂單成立後可否更改付款方式?\"],\"text\":[\"<p>訂單成立後是無法更改付款方式, 除收件人,收件地址需更改則建議立即連絡客</p><p>服人員為您更改,若商品已寄出則無法再更改了!</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"結帳後還能加購商品或更改付款方式嗎?\"],\"text\":[\"<p>因結帳後系統已完成訂單作業,所以恕無法再加購商品了! 也無法更改付款方式了!</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"可辦理退貨嗎?\"],\"text\":[\"<p>除了產品本身有瑕疵外, 很抱歉一律無法退換貨!</p>\"],\"img\":[]}],[]]','faq',1,0),(2,'',0,'0000-00-00','退換貨','退換貨','','[[],[{\"view_id\":\"1\",\"input\":[\"如何退貨換貨?(僅適用於瑕疵品)\"],\"text\":[\"<p>請將商品包裝好,我們會請物流業者前去取回.並於取回收到商品後兩個工作天為您寄出新的商品!</p><p>(不含列假日!)</p>\"],\"img\":[]}],[]]','faq',1,0),(3,'',0,'0000-00-00','運費計算','運費計算','','[[],[{\"view_id\":\"1\",\"input\":[\"運費如何計算\"],\"text\":[\"<p>目前本系列面膜產品,凡購買滿1,000元者免加運費. 未滿者則須加運費70元.(本計算以台灣本島為限, 若是外島或海外需追加運費請先詢問客服人員!)</p>\"],\"img\":[]}],[]]','faq',1,0),(5,'',0,'0000-00-00','美妝','美妝','','[[],[{\"view_id\":\"1\",\"input\":[\"隱形眼鏡哪一個牌子？\"],\"text\":[\"<p>大部分戴的品牌都是海昌唷</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"耳環哪裡買的？\"],\"text\":[\"<p>士林夜市的紅耳朵，陽明戲院旁那條路~</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"守屋的膚質是什麼膚質？\"],\"text\":[\"<p>混合偏乾的膚質</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"唇部都怎麼保養？\"],\"text\":[\"<p>唇部沒有特別保養，我都是擦開架買得到的處唇膏，像是魔唇修護唇霜(夜間)</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"皮膚怎麼保養？\"],\"text\":[\"<p>我以前痘痘肌的時候是會先擦杏仁酸，再使用面膜及乳液。 現在的話都是敷面膜或是拍化妝水唷！</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"長痘痘怎麼辦？\"],\"text\":[\"<p>青春期一定都會長痘痘，但是不要亂擠是重點！ 可以尋求皮膚科或是上網爬文做功課，我是擦杏仁酸以及卸妝方式正確才慢慢改善皮膚的～</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"底妝是什麼牌子的？\"],\"text\":[\"<p>依照天氣我會變換底妝，我最近是用kevin老師的氣墊粉餅</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"燙睫毛器是那個牌子的？\"],\"text\":[\"<p>我在sasa美妝店購買的，eyecurl電睫毛機</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"睫毛膏喜歡用什麼？\"],\"text\":[\"<p>最近喜歡用kate的打底加上睫毛膏</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"遮瑕是用什麼的？\"],\"text\":[\"<p>我的遮瑕也有很多款，最近使用的是revlon遮瑕搭配歐達兒遮瑕</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"電捲棒哪牌？\"],\"text\":[\"<p>我在美材行買的唷！無牌！</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"蓬鬆大旁分要怎麼用？\"],\"text\":[\"<p>我的髮流是往上的，所以沒有刻意吹大旁分喔</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"怎麼樣清粉刺？\"],\"text\":[\"<p>定期每個月去給專業的清粉刺，平常居家就是使用三步驟的清粉刺組加上青春棒使用</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"蜜粉有推薦的嗎？\"],\"text\":[\"<p>我很喜歡bevy c.家的蜜粉，粉撲柔軟、質地輕薄，非常清爽</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"隔離霜什麼的？\"],\"text\":[\"<p>夏天我會使用有控油效果的隔離霜，最近使用的是Maybelline控油透潤持妝乳</p>\"],\"img\":[]}],[]]','about',1,0),(6,'',0,'0000-00-00','個人','個人','','[[],[{\"view_id\":\"1\",\"input\":[\"平常做什麼運動\"],\"text\":[\"<p>我會去健身房先做重訓，再做30分鐘快走</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"常出沒在哪裡？\"],\"text\":[\"<p>天母、士林、東區、信義</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"守屋的工作是什麼？\"],\"text\":[\"<p>我的工作是特助</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"身高多高？\"],\"text\":[\"<p>157公分</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"怎麼瘦臉？\"],\"text\":[\"<p>我是屬於水腫體質，所以我早上化妝前都會用乳液稍微推一下臉頰以及眼下的位置</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"相機是用什麼？\"],\"text\":[\"<p>sony a5100</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"剪輯影片是什麼軟體？\"],\"text\":[\"<p>final cut pro</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"守屋幸慈是本名嗎？\"],\"text\":[\"<p>是本名沒錯，我是中日混血喔</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"會講日文嗎？\"],\"text\":[\"<p>我從小就在台灣出生，所以不會講日文，不過看得懂一些</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"頭髮去哪裡染或整理的？\"],\"text\":[\"<p>Neo Image Hair Studio，設計師是Michelle</p>\"],\"img\":[]},{\"view_id\":\"1\",\"input\":[\"用什麼拍照app？\"],\"text\":[\"<p>snapchat或是玩美相機</p>\"],\"img\":[]}],[]]','about',1,0);
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
UNLOCK TABLES;

