INSERT INTO `product` VALUES (1,'',0,'2014-11-14','The Systemic Circulation','貓爵魅惑CC霜','猫爵魅惑CC霜','','<p>多效合一的極致亮澤 CC Creme，可立即亮白肌膚，獨特鎖水配方技術&nbsp; 有效防水、控油防止肌膚泛光，達到全天候清新舒爽的效果展現完美色能有遮瑕與均勻膚色，讓肌膚展現最自然剔透的零疵質感。</p>\n\n<p>&nbsp;</p>\n','<p>多效合一的极致亮泽CC Creme，可立即亮白肌肤，独特锁水配方技术有效防水、控油防止肌肤泛光，达到全天候清新舒爽的效果展现完美色能有遮瑕与均匀肤色，让肌肤展现最自然剔透的零疵质感。</p>\n','[[],[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/ca39872c3e1946a6bed782c2b454b6eb_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/a70158572cf9aa4003969fe640479cc8_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/e25e3d4c183462d42f1c076234aa14d2_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/be18ae85eb7b7cd0040f76bfd2ee2838_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/374a42ebc07105b3cf5997dceed6aea6_resize.jpg\"]}],[{\"view_id\":\"1\",\"text\":[\"<p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">璀璨系列环保皮革材质</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">&nbsp;</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">100%真皮内里增加穿着后的舒适度</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">基本款实搭尖头细跟高跟鞋</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">浅里剪裁鞋面</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">微厚底台拉长小腿曲线</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">鞋底别出心裁镶上品牌专属钻石爱心五金</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\"><br style=\\\"margin: 0px; padding: 0px;\\\" /><br style=\\\"margin: 0px; padding: 0px;\\\" />&nbsp;跟高：7.5CM</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">&nbsp;</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\">&nbsp;</p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\"><span style=\\\"margin: 0px; padding: 0px;\\\"><font color=\\\"#548dd4\\\" style=\\\"margin: 0px; padding: 0px;\\\">※拍摄商品照片时，除尽量避免色差外，并于商品介绍中说明材质，以提供消费者完整且清楚的商品资讯，但仍有可能因电脑萤幕色差与个人认知而有些许差异。</font></span></p><p style=\\\"padding: 0px; line-height: 21.75px; font-family: Arial, Helvetica, Verdana, Tahoma, sans-serif; border: none; color: rgb(51, 51, 51); font-weight: normal; margin: 0px 0px 15px !important; box-shadow: none !important; background-image: none !important; background-attachment: initial !important; background-size: initial !important; background-origin: initial !important; background-clip: initial !important; background-position: initial !important; background-repeat: initial !important;\\\"><span style=\\\"margin: 0px; padding: 0px; background-color: rgb(255, 255, 0);\\\"><span style=\\\"margin: 0px; padding: 0px; color: rgb(84, 141, 212);\\\"><font color=\\\"#548dd4\\\" style=\\\"margin: 0px; padding: 0px;\\\">※此鞋款版型较合脚，建议购买时选购大一号尺寸穿起来会更加舒适喔！</font></span></span></p>\"],\"img\":[\"\"]}]]','',1,1,'2014-11-14 11:24:51','2015-01-24 00:40:52',1380,0,'CC Cream','The Systemic Circulation CC Cream','The Systemic Circulation CC Cream'),(11,'',0,'2015-02-03','Spotless Mind','Spotless Mind','Spotless Mind','','','','[[],[],[]]','',1,1,'2015-02-03 19:28:49','2015-02-08 17:19:10',1980,0,'Hand mode coffee','訂製手烘咖啡','Hand made coffee'),(3,'',0,'2014-12-12','Triangular Eyebrow','貓爵魅惑三角眉筆','猫爵魅惑三角眉笔','','<p>有專利認證，筆蕊軟硬適中，能均勻上色，延展性佳、不結塊，使眉色更自然、持久。完美的三角切面，即使用到最後一小段，銳面依然完美如初。</p>\n\n<p>&nbsp;</p>\n','<p>有专利认证，笔蕊软硬适中，能均匀上色，延展性佳、不结块，使眉色更自然、持久。完美的三角切面，即使用到最后一小段，锐面依然完美如初。</p>\n','[[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-21/80bee21a7a22b521b18b3e39c8880a08_resize.jpg\"]}],[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/0ae202333cdf83b716daf0e0717c7447_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/e9ddb694bcc7609805c5f2e6e77eec30_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/0d310858b0be17e61b9d641d65313f36_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/a58085512f9256c58cba0d242f184c57_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/4b17906237e71dd26993daec496f2d81_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/1147e763b3149b60a7b83ff1391cb2c1_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/4e271eba983a3133e2f6a78d387447c5_resize.jpg\"]}],[]]','',1,1,'2014-12-12 16:05:01','2015-02-15 20:08:55',480,0,'With Brush','Triangular Eyebrow With Brush','Triangular Eyebrow'),(4,'',0,'2014-12-12','Liquid Eye Liner','貓爵魅惑眼線液','猫爵魅惑眼线液','','<p>色彩烏黑具光澤，可展現魅力大眼妝感。極細柔軟筆尖，描繪極細線條。獨特配方持久抗暈染。</p>\n\n<p>&nbsp;</p>\n','<p>色彩乌黑具光泽，可展现魅力大眼妆感。极细柔软笔尖，描绘极细线条。独特配方持久抗晕染。</p>\n','[[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-21/6ae219706d2ce8591e9328a913fafe43_resize.jpg\"]}],[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/57fc57db827378086ca18eadfa88ceee_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/300f93ad5993e148b88810ab6a6d306c_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/e80c8bf01951854da49827b118eb3d3d_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/c06896396c844a07dfb804dede6988c1_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/0c3650c828d215a1443fa28e34ca51a0_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/c5bb0ed80b97c5ece1c645ca17ae9152_resize.jpg\"]}],[]]','',1,1,'2014-12-12 18:03:19','2015-01-24 16:57:35',580,0,'Waterproof','Waterproof Liquid Eye Liner','Waterproof Liquid Eye Liner'),(5,'',0,'2014-12-15','Flexible Cushion Foundation','貓爵魅惑氣墊CC水凝霜','猫爵魅惑气垫CC水凝霜','','<p>擺脫厚重，輕薄服貼 3秒塑造水美肌。</p>\n\n<p>SPF50 ★可有效隔離紫外線防止UVA/UVB UVA/UVBUVA/UVB UVA/UVB傷害。</p>\n\n<p>將美白、防曬、抗汗、紓緩、底妝等5大功能的有效成分儲存於海綿內，使肌膚享受清新紓緩感的概念氣墊 CC 水凝霜，可更均勻輕薄的服貼於肌膚有如裸妝般。</p>\n\n<p>&nbsp;</p>\n','<p>摆脱厚重，轻薄服贴3秒塑造水美肌。</p>\n\n<p>SPF50 ★可有效隔离紫外线防止UVA/UVB UVA/UVBUVA/UVB UVA/UVB伤害。</p>\n\n<p>将美白、防晒、抗汗、纾缓、底妆等5大功能的有效成分储存于海绵内，使肌肤享受清新纾缓感的概念气垫CC 水凝霜，可更均匀轻薄的服贴于肌肤有如裸妆般。</p>\n','[[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-21/7fc3cd11b1ab299c09dbe4d46c941503_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"\"]}],[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/fd9c20b9e003db11c1b9b46af0b0a967_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/cff375e5cad50db6437ade63b0176bfc_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/f0bc05537a23c04ddf1755e6590fb54e_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/f229b8e6d365f48214544d7c3d6a15e3_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/d5c1132a91155a42edb1e0291d5ecc58_resize.jpg\"]}],[]]','',1,1,'2014-12-15 20:12:19','2015-01-24 01:04:56',1380,0,'Flexible Cushion Foundation','Flexible Cushion Foundation','Flexible Cushion Foundation'),(6,'',0,'2014-12-15','Perfect Cover Concealer Plate','貓爵魅惑三色遮瑕凝霜','猫爵魅惑三色遮瑕凝霜','','<p>打造立體完美五官、提亮、遮瑕、修容。</p>\n\n<p>獨特有效配方具防汗、控油效果絕佳，在夏季高溫等出汗時，皆有效保持良好遮瑕力且不易脫妝，除此之外還含多重保濕成分，有效避免眼部周圍的乾燥、及防止細紋的產生，不易有遮瑕後的厚重感。</p>\n\n<p>&nbsp;</p>\n','<p>打造立体完美五官、提亮、遮瑕、修容。</p>\n\n<p>独特有效配方具防汗、控油效果绝佳，在夏季高温等出汗时，皆有效保持良好遮瑕力且不易脱妆，除此之外还含多重保湿成分，有效避免眼部周围的干燥、及防止细纹的产生，不易有遮瑕后的厚重感。</p>\n','[[{\"view_id\":\"1\",\"text\":[\"<p>XXXXX</p>\"],\"img\":[\"2015-01-21/ce9fb22ccb5d55ec6a3434c6f8b466dd_resize.jpg\"]}],[{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/de4b09ae350640004dd1091226cc8981_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/2737e52f6a88595b833ba4b538681633_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/f91366d0cf0c21edfe219fd7308c5b9d_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/158aa125f33ba2862f5f52662f6309da_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/55acf47490c1762ffb7aee0282a87e5c_resize.jpg\"]},{\"view_id\":\"1\",\"text\":[\"\"],\"img\":[\"2015-01-24/f220404078cff620798ff1b8af7edf08_resize.jpg\"]}],[]]','',1,1,'2014-12-15 20:29:33','2015-01-24 00:54:37',1380,0,'with 3 Color','Perfect Cover Concealer Plate','Perfect Cover Concealer Plate'),(9,'',0,'2015-01-14','Eternal Sunshine','Eternal Sunshine','Eternal Sunshine','','<p><strong>進口產地：</strong>巴西(台灣在地手工烘焙)<br />\n<strong>商品尺寸：</strong>約長190X寬90X高55mm<br />\n<strong>商品重量：</strong>150 克 &plusmn; 5% (包)<br />\n<strong>商品成份：</strong>100%咖啡豆<br />\n<strong>保存期限：</strong>保存期限2年(有效日期如包裝上標示)<br />\n<strong>保存方法：</strong>拆封後請儘速飲用，避免陽光直射及高溫潮濕</p>\n','','[[],[],[]]','',1,1,'2015-01-14 14:08:13','2015-02-04 14:14:59',1980,1680,'Hand made coffee','訂製手烘咖啡','Hand made coffee'),(12,'',0,'2016-04-12','Dolliipop激光煥白保濕面膜\n','Dolliipop激光煥白保濕面膜\n','','','','','[[],[],[]]','',1,1,'2016-04-12 19:42:30','2016-04-12 19:42:30',120,120,'','',''),(13,'',0,'2016-04-12','Dolliipop激光煥白保濕面膜\n','Dolliipop激光煥白保濕面膜\n','','','','','[[],[],[]]','',1,1,'2016-04-12 19:43:20','2016-04-12 19:43:20',120,120,'','',''),(14,'',0,'2016-04-12','Dolliipop激光煥白保濕面膜\n','Dolliipop激光煥白保濕面膜\n','','','','','[[],[],[]]','',1,1,'2016-04-12 19:43:46','2016-04-12 19:43:46',120,120,'','','');
